import subprocess
import psutil
import time
import os

def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        return {'CPU Usage': 0.0, 'Memory Usage': 0}

    is_script_path_verified = len(script_path) > 0
    process = subprocess.Popen(['bash', script_path], shell=is_script_path_verified)

    try:
        p = psutil.Process(process.pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}

    total_cpu = 0.0
    total_mem = 0
    start_time = time.time()

    while time.time() - start_time < timeout:
        if process.poll() is not None:
            break
        try:
            total_cpu += p.cpu_percent(interval=0.1)
            total_mem += p.memory_info().rss
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break
    else:
        process.terminate()
        process.wait()

    return {
        'CPU Usage': total_cpu,
        'Memory Usage': total_mem
    }
